INSERT INTO billing.invoice_items (
    invoice_id, order_item_id, name, quantity, unit, unit_price, vat_rate, position
)
SELECT #{invoiceId}, #{orderItemId}, #{name}, #{quantity}, #{unit},
       #{unitPrice}, #{vatRate}, #{position}
WHERE EXISTS (
    SELECT 1 FROM billing.invoices i
    WHERE i.id = #{invoiceId} AND i.status = 'DRAFT'::billing.invoice_status
)
